#!/usr/bin/env python3

import os
import sys
from pathlib import Path

def find_broken_symlinks(directory):
    """Find all broken symbolic links in a directory and its subdirectories."""
    broken_links = []

    try:
        # Walk through the directory tree
        for root, dirs, files in os.walk(directory):
            # Check for broken symlinks in directories
            for dir_name in dirs:
                full_path = os.path.join(root, dir_name)
                if os.path.islink(full_path):
                    if not os.path.exists(full_path):
                        broken_links.append(os.path.abspath(full_path))

            # Check for broken symlinks in files
            for file_name in files:
                full_path = os.path.join(root, file_name)
                if os.path.islink(full_path):
                    if not os.path.exists(full_path):
                        broken_links.append(os.path.abspath(full_path))

    except Exception as e:
        print(f"Error scanning directory: {e}", file=sys.stderr)

    return broken_links

if __name__ == "__main__":
    workspace_dir = "/tmp/mcp-workspace"

    print("Searching for broken symbolic links...")
    broken_links = find_broken_symlinks(workspace_dir)

    # Write results to file
    output_file = "/tmp/mcp-workspace/broken_links.txt"
    try:
        with open(output_file, 'w') as f:
            for link in sorted(broken_links):
                f.write(f"{link}\n")

        print(f"Found {len(broken_links)} broken symbolic links.")
        print(f"Results written to {output_file}")

        # Also print to stdout for visibility
        if broken_links:
            print("\nBroken symbolic links:")
            for link in sorted(broken_links):
                print(f"  {link}")
        else:
            print("No broken symbolic links found.")

    except Exception as e:
        print(f"Error writing to output file: {e}", file=sys.stderr)
        sys.exit(1)

