import os
import sys
from pathlib import Path

def find_all_symlinks(directory):
    """Find all symbolic links in a directory and its subdirectories."""
    symlinks = []
    broken_symlinks = []

    # Walk through the directory tree
    for root, dirs, files in os.walk(directory):
        # Check for symlinks in directories
        for dir_name in dirs:
            full_path = os.path.join(root, dir_name)
            try:
                if os.path.islink(full_path):
                    symlinks.append(full_path)
                    if not os.path.exists(full_path):
                        broken_symlinks.append(full_path)
            except OSError:
                pass  # Skip inaccessible files

        # Check for symlinks in files
        for file_name in files:
            full_path = os.path.join(root, file_name)
            try:
                if os.path.islink(full_path):
                    symlinks.append(full_path)
                    if not os.path.exists(full_path):
                        broken_symlinks.append(full_path)
            except OSError:
                pass  # Skip inaccessible files

    return symlinks, broken_symlinks

if __name__ == "__main__":
    workspace_dir = "/tmp/mcp-workspace"

    print("Scanning for symbolic links...")
    all_symlinks, broken_symlinks = find_all_symlinks(workspace_dir)

    print(f"Total symbolic links found: {len(all_symlinks)}")
    print(f"Broken symbolic links: {len(broken_symlinks)}")

    # Write broken links to file
    with open("/tmp/mcp-workspace/broken_links.txt", "w") as f:
        for link in sorted(broken_symlinks):
            f.write(f"{os.path.abspath(link)}\n")

    if broken_symlinks:
        print("\nBroken symbolic links:")
        for link in sorted(broken_symlinks):
            print(f"  {link}")
    else:
        print("No broken symbolic links found.")
